// ITEM & RECIPE RECONSTRUCTION — authored design layer (Control Tower order, 2026-11-15).
//
// This file holds ONLY what cannot be read from live code: why each of the 157 items exists, which family it belongs
// to, how it is meant to be acquired, why each formula has the shape it has, and the family rules a player can learn.
// Every number in the master document (bills, yields, stations, tiers, times, struct costs, upgrade costs, recycler
// returns, Last Island source figures) is read from the live catalog / ledgers by tests/item-crafting-master.test.ts,
// which joins both into web/ref/last-island-copy-first/ITEM_CRAFTING_MASTER.{json,md}. Nothing here is imported by
// the game at run time.
//
// Phase boundary: this is a crafting-language design. It says nothing about where an item is found, how often, or in
// which container: `WORLD_ONLY` is an acquisition-policy intent, not a claim that a map source exists.

export type AcquirePolicy = 'CRAFT_ONLY' | 'WORLD_ONLY' | 'BOTH' | 'SPECIAL_AUTHORITY';
export type Decision = 'KEEP' | 'REVISE' | 'RETIRED';

export const FAMILY_ORDER = ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11'] as const;
export type FamilyId = typeof FAMILY_ORDER[number];

