  spares: 'fitted mechanical pieces', mechanical_gear: 'a mechanism that turns', metal_pipe: 'tube or hollow structural member', iron_plate: 'protective sheet metal', metal_blade: 'cutting edge',
  needle_thread: 'sewn assembly', glass: 'lens, still or vessel', crystal: 'Core focus', sulfur: 'fire element', shell: 'lime (glass flux) or water element', herb: 'medicine or nature element',
